parameters.query:
WITH bind AS (SELECT $1::jsonb data),
input AS (
 SELECT (data->>'telegram_id')::bigint telegram_id,NULLIF(btrim(data->>'username'),'') username,data->>'action' action,NULLIF(btrim(data->>'first_name'),'') first_name,NULLIF(btrim(data->>'answer'),'') answer FROM bind
),
telegram_lock AS (SELECT pg_advisory_xact_lock(input.telegram_id) FROM input),
existing_account AS (
 SELECT ta.user_id FROM telegram_accounts ta CROSS JOIN input CROSS JOIN telegram_lock WHERE ta.telegram_id=input.telegram_id
),
created_user AS (
 INSERT INTO users(role) SELECT NULL FROM input CROSS JOIN telegram_lock WHERE NOT EXISTS(SELECT 1 FROM existing_account) RETURNING id
),
created_account AS (
 INSERT INTO telegram_accounts(user_id,telegram_id,username) SELECT created_user.id,input.telegram_id,input.username FROM created_user CROSS JOIN input RETURNING user_id
),
resolved AS (SELECT user_id FROM existing_account UNION ALL SELECT user_id FROM created_account),
username_update AS (
 UPDATE telegram_accounts ta SET username=input.username FROM input,resolved WHERE ta.telegram_id=input.telegram_id AND ta.user_id=resolved.user_id AND ta.username IS DISTINCT FROM input.username RETURNING ta.user_id
)
SELECT resolved.user_id::text,input.action,input.first_name,input.answer,input.username,EXISTS(SELECT 1 FROM created_account) AS is_new
FROM resolved CROSS JOIN input;
